-- Migration 20261028193827_status_link: generated by drizzle-kit, RLS and functions hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #88)
-- Client status links (#88, ADR 0049): status_link and status_link_access are tenant tables under FORCE RLS on app.workspace_id. app_status_link_view() is the one cross-workspace read (a signed-out client has no workspace), by token hash only: it returns the authored payload and the state of the link. app_status_link_record_view() writes one status_link_access row (time and ua class, no IP) for a link that is still valid, so a view is only counted once the service has checked the flag. app_status_link_purge_targets() lists workspace ids with links expired for 30 days, for the nightly retention job. Additive only: new tables, two policies and three functions; nothing existing is altered or dropped.
CREATE TABLE "status_link" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"matter_id" uuid NOT NULL,
	"client_contact_id" uuid NOT NULL,
	"token_hash" text NOT NULL,
	"payload" jsonb NOT NULL,
	"language" text DEFAULT 'en' NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	"purged_at" timestamp with time zone,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "status_link_token_hash_uq" UNIQUE("token_hash"),
	CONSTRAINT "status_link_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "status_link_payload_chk" CHECK (jsonb_typeof("status_link"."payload") = 'object'),
	CONSTRAINT "status_link_language_chk" CHECK (language in ('en', 'ta', 'kn'))
);
--> statement-breakpoint
CREATE TABLE "status_link_access" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"link_id" uuid NOT NULL,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	"ua_class" text NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "status_link_access_ua_chk" CHECK (ua_class in ('mobile', 'desktop', 'bot', 'other'))
);
--> statement-breakpoint
