CREATE FUNCTION app_status_link_view(p_hash text)
  RETURNS TABLE (id uuid, workspace_id uuid, advocate_name text, payload jsonb, language text, expires_at timestamptz, revoked_at timestamptz, purged_at timestamptz)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$ SELECT s.id, s.workspace_id, (SELECT u.name FROM "user" u WHERE u.id = s.created_by), s.payload, s.language, s.expires_at, s.revoked_at, s.purged_at FROM status_link s WHERE s.token_hash = p_hash $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_status_link_view(text) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_status_link_view(text) TO causedeck_app;--> statement-breakpoint
CREATE FUNCTION app_status_link_record_view(p_link uuid, p_ua text)
  RETURNS void
  LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    INSERT INTO status_link_access (link_id, workspace_id, ua_class)
    SELECT s.id, s.workspace_id, p_ua FROM status_link s
    WHERE s.id = p_link AND s.revoked_at IS NULL AND s.purged_at IS NULL AND s.expires_at > now()
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_status_link_record_view(uuid, text) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_status_link_record_view(uuid, text) TO causedeck_app;--> statement-breakpoint
CREATE FUNCTION app_status_link_purge_targets(p_now timestamptz)
  RETURNS TABLE (workspace_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT DISTINCT s.workspace_id FROM status_link s
    WHERE s.purged_at IS NULL AND s.expires_at <= p_now - interval '30 days'
    ORDER BY s.workspace_id
    LIMIT 1000
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_status_link_purge_targets(timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_status_link_purge_targets(timestamptz) TO causedeck_app;
